pthread_mutex_t mtx;
pthread_cond_t cond;
int condition_met = 0;

// Waiter logic
pthread_mutex_lock(&mtx);

while (!condition_met) {
    // Atomically unlocks mtx and suspends thread
    // Re-locks mtx upon wakeup
    pthread_cond_wait(&cond, &mtx);
}

// Access shared data here
pthread_mutex_unlock(&mtx);

